const binaryData = firstItem.binary || {};
const keys = Object.keys(binaryData);
const items = [];

for (const key of keys) {
  const file = binaryData[key];
  items.push({
    json: {
      filename: String(file.fileName || key),
      mimetype: String(file.mimeType || ''),
    },
    binary: {
      Course_materials: file
    }
  });
}

return items;

